package com.jnapanam.sportszone.commerce.service;
import static com.jnapanam.sportszone.commerce.dto.CommerceDtos.*;
import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class CommerceService{
 private final JdbcTemplate jdbc;public CommerceService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public List<Category> categories(){return jdbc.query("select * from commerce_categories where status='ACTIVE' order by display_order,name",(r,n)->new Category(r.getObject("id",UUID.class),r.getString("code"),r.getString("name"),r.getString("name_kn"),r.getString("description"),r.getString("image_url"),r.getInt("display_order"),r.getString("status")));}
 public List<Product> products(String category){String sql="""select p.*,c.code category_code from commerce_products p join commerce_categories c on c.id=p.category_id where p.status='ACTIVE' and c.status='ACTIVE' and (? is null or upper(c.code)=upper(?)) order by p.name""";return jdbc.query(sql,(r,n)->product(r),category,category);}
 public Product product(UUID id){return jdbc.queryForObject("select p.*,c.code category_code from commerce_products p join commerce_categories c on c.id=p.category_id where p.id=? and p.status='ACTIVE'",(r,n)->product(r),id);}
 private Product product(ResultSet r)throws SQLException{UUID id=r.getObject("id",UUID.class);List<Variant> variants=jdbc.query("select * from commerce_variants where product_id=? and status='ACTIVE' order by price_paise",(v,n)->new Variant(v.getObject("id",UUID.class),v.getString("sku"),v.getString("label"),v.getLong("price_paise"),v.getInt("stock_quantity"),v.getString("status")),id);return new Product(id,r.getString("category_code"),r.getString("sku"),r.getString("name"),r.getString("name_kn"),r.getString("description"),r.getString("description_kn"),r.getString("image_url"),r.getDouble("tax_percent"),r.getString("status"),variants);}
 public Cart cart(UUID user){List<CartItem> items=jdbc.query("""select ci.id,ci.variant_id,p.name,v.label,p.image_url,v.price_paise,ci.quantity,v.stock_quantity from commerce_cart_items ci join commerce_variants v on v.id=ci.variant_id join commerce_products p on p.id=v.product_id where ci.user_id=? order by ci.created_at""",(r,n)->new CartItem(r.getObject("id",UUID.class),r.getObject("variant_id",UUID.class),r.getString("name"),r.getString("label"),r.getString("image_url"),r.getLong("price_paise"),r.getInt("quantity"),r.getLong("price_paise")*r.getInt("quantity"),r.getInt("stock_quantity")),user);return new Cart(items,items.stream().mapToLong(CartItem::lineTotalPaise).sum());}
 public Cart putCart(UUID user,CartRequest request){Integer stock=jdbc.queryForObject("select stock_quantity from commerce_variants where id=? and status='ACTIVE'",Integer.class,request.variantId());if(stock==null||request.quantity()>stock)throw new IllegalArgumentException("Only "+(stock==null?0:stock)+" item(s) available");jdbc.update("""insert into commerce_cart_items(user_id,variant_id,quantity) values(?,?,?) on conflict(user_id,variant_id) do update set quantity=excluded.quantity,updated_at=now()""",user,request.variantId(),request.quantity());return cart(user);}
 public Cart removeCart(UUID user,UUID variant){jdbc.update("delete from commerce_cart_items where user_id=? and variant_id=?",user,variant);return cart(user);}
 @Transactional public Order checkout(UUID user,CheckoutRequest r){
  String fulfil=r.fulfilmentType().toUpperCase();if(!Set.of("PICKUP","DELIVERY").contains(fulfil))throw new IllegalArgumentException("Fulfilment type must be PICKUP or DELIVERY");if(fulfil.equals("DELIVERY")&&(blank(r.addressLine())||blank(r.city())||blank(r.state())||blank(r.postalCode())))throw new IllegalArgumentException("Delivery address, city, state and postal code are required");
  var rows=jdbc.queryForList("""select ci.variant_id,ci.quantity,v.stock_quantity,v.price_paise,v.sku,v.label,p.id product_id,p.name,p.tax_percent from commerce_cart_items ci join commerce_variants v on v.id=ci.variant_id join commerce_products p on p.id=v.product_id where ci.user_id=? order by ci.created_at for update of v""",user);if(rows.isEmpty())throw new IllegalArgumentException("Cart is empty");
  long subtotal=0,tax=0;for(var x:rows){int qty=(Integer)x.get("quantity"),stock=(Integer)x.get("stock_quantity");if(qty>stock)throw new IllegalArgumentException(x.get("name")+" has only "+stock+" item(s) available");long line=((Number)x.get("price_paise")).longValue()*qty;subtotal+=line;tax+=Math.round(line*((Number)x.get("tax_percent")).doubleValue()/100d);}
  long delivery=fulfil.equals("DELIVERY")?5000:0,total=subtotal+tax+delivery;UUID id=UUID.randomUUID();String number="JNZ-SHOP-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();String method=r.paymentMethod().toUpperCase();String payStatus=method.equals("PAY_AT_PICKUP")?"PENDING":"PENDING";
  jdbc.update("""insert into commerce_orders(id,order_number,user_id,status,fulfilment_type,payment_method,payment_status,subtotal_paise,tax_paise,delivery_fee_paise,total_paise,recipient_name,mobile,address_line,city,state,postal_code) values(?,?,?,'PLACED',?,?,?,?,?,?,?,?,?,?,?,?,?)""",id,number,user,fulfil,method,payStatus,subtotal,tax,delivery,total,r.recipientName(),r.mobile(),r.addressLine(),r.city(),r.state(),r.postalCode());
  for(var x:rows){int qty=(Integer)x.get("quantity");long price=((Number)x.get("price_paise")).longValue(),line=price*qty,itemTax=Math.round(line*((Number)x.get("tax_percent")).doubleValue()/100d);UUID variant=(UUID)x.get("variant_id");jdbc.update("insert into commerce_order_items(order_id,product_id,variant_id,sku,product_name,variant_label,unit_price_paise,tax_paise,quantity,line_total_paise) values(?,?,?,?,?,?,?,?,?,?)",id,x.get("product_id"),variant,x.get("sku"),x.get("name"),x.get("label"),price,itemTax,qty,line+itemTax);jdbc.update("update commerce_variants set stock_quantity=stock_quantity-? where id=?",qty,variant);jdbc.update("insert into commerce_stock_movements(variant_id,quantity_delta,reason,reference_id,actor_id) values(?,?,'ORDER',?,?)",variant,-qty,id,user);}
  jdbc.update("delete from commerce_cart_items where user_id=?",user);return order(user,id);
 }
 public List<Order> orders(UUID user){return jdbc.query("select id from commerce_orders where user_id=? order by created_at desc",(r,n)->order(user,r.getObject(1,UUID.class)),user);}
 public Order order(UUID user,UUID id){return jdbc.queryForObject("select * from commerce_orders where id=? and user_id=?",(r,n)->mapOrder(r),id,user);}
 private Order mapOrder(ResultSet r)throws SQLException{UUID id=r.getObject("id",UUID.class);List<OrderItem> items=jdbc.query("select * from commerce_order_items where order_id=?",(x,n)->new OrderItem(x.getString("sku"),x.getString("product_name"),x.getString("variant_label"),x.getLong("unit_price_paise"),x.getInt("quantity"),x.getLong("tax_paise"),x.getLong("line_total_paise")),id);return new Order(id,r.getString("order_number"),r.getString("status"),r.getString("fulfilment_type"),r.getString("payment_method"),r.getString("payment_status"),r.getLong("subtotal_paise"),r.getLong("tax_paise"),r.getLong("delivery_fee_paise"),r.getLong("total_paise"),r.getString("recipient_name"),r.getString("mobile"),r.getString("address_line"),r.getString("city"),r.getString("state"),r.getString("postal_code"),r.getTimestamp("created_at").toInstant(),items);}
 @Transactional public Order cancel(UUID user,UUID id,String reason){Order o=order(user,id);if(!Set.of("PLACED","CONFIRMED").contains(o.status()))throw new IllegalArgumentException("This order cannot be cancelled");jdbc.update("update commerce_orders set status='CANCELLED',cancellation_reason=?,updated_at=now() where id=?",reason,id);jdbc.queryForList("select variant_id,quantity from commerce_order_items where order_id=?",id).forEach(x->{UUID v=(UUID)x.get("variant_id");int q=(Integer)x.get("quantity");jdbc.update("update commerce_variants set stock_quantity=stock_quantity+? where id=?",q,v);jdbc.update("insert into commerce_stock_movements(variant_id,quantity_delta,reason,reference_id,actor_id) values(?,?,'CANCELLATION',?,?)",v,q,id,user);});return order(user,id);}
 private boolean blank(String x){return x==null||x.isBlank();}
}
